#include "HSREquipmentStatAggregator.h"
bool UHSREquipmentStatAggregator::AddInstance(const FHSREquipmentInstance& I,FHSREquipmentAggregate& O){ if(!I.InstanceId.IsValid()||I.DefinitionId.IsNone()||I.EnhancementLevel<0)return false; for(const auto& M:I.Modifiers){if(!FMath::IsFinite(M.Value)||M.Value<0.f)return false; float* D=nullptr; switch(M.Stat){case EHSREquipmentStat::MaxHealth:D=&O.MaxHealth;break;case EHSREquipmentStat::Attack:D=&O.Attack;break;case EHSREquipmentStat::Defense:D=&O.Defense;break;case EHSREquipmentStat::Speed:D=&O.Speed;break;} if(D==nullptr||!FMath::IsFinite(*D+M.Value))return false; *D+=M.Value;} return true; }
bool UHSREquipmentStatAggregator::Aggregate(const FHSREquipmentLoadout& L,int64 R,FHSREquipmentAggregate& O){if(R<0)return false; FHSREquipmentAggregate T;T.Revision=R; for(const auto& P:L.Equipment)if(!AddInstance(P.Value,T))return false; for(const auto& P:L.Relics)if(!AddInstance(P.Value,T))return false; O=T; return true;}
